from datetime import date, timedelta
from typing import List, Optional, Set

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: Optional[List[date]] = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # Track used leave days per employee per year
        # Structure: {employee: {year: used_days}}
        self.used_leave = {}

    def _is_weekend(self, d: date) -> bool:
        """Check if a date is Saturday (5) or Sunday (6)"""
        return d.weekday() >= 5

    def _is_holiday(self, d: date) -> bool:
        """Check if a date is in the holidays set"""
        return d in self.holidays

    def _is_working_day(self, d: date) -> bool:
        """Check if a date is a working day (not weekend and not holiday)"""
        return not self._is_weekend(d) and not self._is_holiday(d)

    def _get_year(self, d: date) -> int:
        """Get the year of a date"""
        return d.year

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        # Check if end date is before start date
        if end < start:
            raise ValueError("End date cannot be before start date")

        # Check if request is made less than 3 days before start date
        if (start - today).days < 3:
            raise ValueError("Request must be made at least 3 days before start date")

        # Calculate working days in the range [start, end] inclusive
        current = start
        leave_days_used = 0

        # Initialize employee's tracking if not exists
        if employee not in self.used_leave:
            self.used_leave[employee] = {}

        # Get the year for this request
        year = self._get_year(start)

        # Count working days in the requested period
        while current <= end:
            if self._is_working_day(current):
                leave_days_used += 1
            current += timedelta(days=1)

        # Update used leave days for this employee and year
        if year not in self.used_leave[employee]:
            self.used_leave[employee][year] = 0
        self.used_leave[employee][year] += leave_days_used

        return leave_days_used

    def remaining(self, employee: str, year: int) -> int:
        """Return remaining leave days for the employee in the given year."""
        # If employee has no record for this year, they have all days available
        if employee not in self.used_leave or year not in self.used_leave[employee]:
            return self.days_per_year

        used = self.used_leave[employee][year]
        return max(0, self.days_per_year - used)
